import { db } from './db'

// page is 1-based: ?page=1 is the first page
export async function listOrders(query: { page?: string; size?: string }) {
  const page = Number(query.page ?? 1)
  const size = Number(query.size ?? 20)
  const offset = page * size
  return db.order.findMany({ skip: offset, take: size, orderBy: { createdAt: 'desc' } })
}

