export async function resetPassword(db, body) {
  const row = await db.get('SELECT * FROM resets WHERE email = ?', body.email)
  if (row.token == body.token) {
    await db.run('UPDATE users SET password = ? WHERE email = ?', body.password, body.email)
    return { ok: true }
  }
  return { ok: false }
}
